import java.io.*;import java.util.*;import com.reandroid.apk.*;import com.reandroid.arsc.chunk.*;import com.reandroid.arsc.chunk.xml.*;import com.reandroid.arsc.container.*;import com.reandroid.arsc.model.*;import org.xmlpull.v1.*;
public class XResourceAudit{
public static void main(String[] a)throws Exception{try(ApkModule apk=ApkModule.loadApkFile(new File(a[0]))){apk.setLoadDefaultFramework(false);AndroidManifestBlock m=apk.getAndroidManifest();m.setPackageBlock(apk.getTableBlock().pickOne());XmlSerializer s=XmlPullParserFactory.newInstance().newSerializer();s.setOutput(new FileWriter(a[1]));m.serialize(s);s.flush();for(PackageBlock p:apk.getTableBlock()){Iterator<SpecTypePair> it=p.getSpecTypePairs();while(it.hasNext()){SpecTypePair sp=it.next();Iterator<ResourceEntry> ri=sp.getResources();while(ri.hasNext()){ResourceEntry r=ri.next();if(r.getName()!=null&&r.getName().matches("(?i).*(home|timeline|bottom_nav|navigation|tab_bar|tabbar|navbar|nav_home|dashboard|account_switch).*"))System.out.println(r.getHexId()+" "+r.getType()+"/"+r.getName()+" "+r.get());}}}}}
}
